pub struct ExecutePublicAutomationCpiBuilder<'a, 'b> {
  instruction: Box<ExecutePublicAutomationCpiBuilderInstruction<'a, 'b>>,
}

impl<'a, 'b> ExecutePublicAutomationCpiBuilder<'a, 'b> {
  pub fn new(program: &'b solana_account_info::AccountInfo<'a>) -> Self {
    let instruction = Box::new(ExecutePublicAutomationCpiBuilderInstruction {
      __program: program,
              authority: None,
              satrush_config: None,
              board: None,
              round: None,
              public_automation: None,
              usd_mint: None,
              automation_usd_ata: None,
              board_usd_ata: None,
              public_deployment: None,
              miner: None,
              slot_hashes: None,
              token_program: None,
              system_program: None,
              event_authority: None,
              program: None,
                                            selection_mask: None,
                    __remaining_accounts: Vec::new(),
    });
    Self { instruction }
  }
      /// The crank (round authority); pays the deployment rent, recovered at
/// settle.
#[inline(always)]
    pub fn authority(&mut self, authority: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.authority = Some(authority);
                    self
    }
      #[inline(always)]
    pub fn satrush_config(&mut self, satrush_config: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.satrush_config = Some(satrush_config);
                    self
    }
      #[inline(always)]
    pub fn board(&mut self, board: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.board = Some(board);
                    self
    }
      /// Round the automation deploys into. Must be the board's current round.
#[inline(always)]
    pub fn round(&mut self, round: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.round = Some(round);
                    self
    }
      /// The automation being executed; its `authority` field keys the
/// deployment and miner PDAs below. A regular Account (boxed): its fields
/// feed seeds, which LazyAccount cannot do.
#[inline(always)]
    pub fn public_automation(&mut self, public_automation: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.public_automation = Some(public_automation);
                    self
    }
      #[inline(always)]
    pub fn usd_mint(&mut self, usd_mint: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.usd_mint = Some(usd_mint);
                    self
    }
      /// The automation's escrow the deploy is funded from.
#[inline(always)]
    pub fn automation_usd_ata(&mut self, automation_usd_ata: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.automation_usd_ata = Some(automation_usd_ata);
                    self
    }
      /// Board's USD deposit pool.
#[inline(always)]
    pub fn board_usd_ata(&mut self, board_usd_ata: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.board_usd_ata = Some(board_usd_ata);
                    self
    }
      /// Per-(user, round) deployment record. Init fails if the user already
/// deployed into this round (manually or via this automation).
#[inline(always)]
    pub fn public_deployment(&mut self, public_deployment: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.public_deployment = Some(public_deployment);
                    self
    }
      /// The user's miner profile; guaranteed to exist by
/// `create_public_automation`, so no `init_if_needed` here (stack + rent).
#[inline(always)]
    pub fn miner(&mut self, miner: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.miner = Some(miner);
                    self
    }
      /// because the sysvar is too large to deserialize. Feeds Random-strategy
/// mask generation only, but is always passed (cheap).
#[inline(always)]
    pub fn slot_hashes(&mut self, slot_hashes: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.slot_hashes = Some(slot_hashes);
                    self
    }
      #[inline(always)]
    pub fn token_program(&mut self, token_program: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.token_program = Some(token_program);
                    self
    }
      #[inline(always)]
    pub fn system_program(&mut self, system_program: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.system_program = Some(system_program);
                    self
    }
      #[inline(always)]
    pub fn event_authority(&mut self, event_authority: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.event_authority = Some(event_authority);
                    self
    }
      #[inline(always)]
    pub fn program(&mut self, program: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
                        self.instruction.program = Some(program);
                    self
    }
                    /// `[optional argument]`
#[inline(always)]
      pub fn selection_mask(&mut self, selection_mask: u32) -> &mut Self {
        self.instruction.selection_mask = Some(selection_mask);
        self
      }
        /// Add an additional account to the instruction.
  #[inline(always)]
  pub fn add_remaining_account(&mut self, account: &'b solana_account_info::AccountInfo<'a>, is_writable: bool, is_signer: bool) -> &mut Self {
    self.instruction.__remaining_accounts.push((account, is_writable, is_signer));
    self
  }
  /// Add additional accounts to the instruction.
  ///
  /// Each account is represented by a tuple of the `AccountInfo`, a `bool` indicating whether the account is writable or not,
  /// and a `bool` indicating whether the account is a signer or not.
  #[inline(always)]
  pub fn add_remaining_accounts(&mut self, accounts: &[(&'b solana_account_info::AccountInfo<'a>, bool, bool)]) -> &mut Self {
    self.instruction.__remaining_accounts.extend_from_slice(accounts);
    self
  }
  #[inline(always)]
  pub fn invoke(&self) -> solana_program_error::ProgramResult {
    self.invoke_signed(&[])
  }
  #[allow(clippy::clone_on_copy)]
  #[allow(clippy::vec_init_then_push)]
  pub fn invoke_signed(&self, signers_seeds: &[&[&[u8]]]) -> solana_program_error::ProgramResult {
          let args = ExecutePublicAutomationInstructionArgs {
                                                              selection_mask: self.instruction.selection_mask.clone(),
                                    };
        let instruction = ExecutePublicAutomationCpi {
        __program: self.instruction.__program,
                  
          authority: self.instruction.authority.expect("authority is not set"),
                  
          satrush_config: self.instruction.satrush_config.expect("satrush_config is not set"),
                  
          board: self.instruction.board.expect("board is not set"),
                  
          round: self.instruction.round.expect("round is not set"),
                  
          public_automation: self.instruction.public_automation.expect("public_automation is not set"),
                  
          usd_mint: self.instruction.usd_mint.expect("usd_mint is not set"),
                  
          automation_usd_ata: self.instruction.automation_usd_ata.expect("automation_usd_ata is not set"),
                  
          board_usd_ata: self.instruction.board_usd_ata.expect("board_usd_ata is not set"),
                  
          public_deployment: self.instruction.public_deployment.expect("public_deployment is not set"),
                  
          miner: self.instruction.miner.expect("miner is not set"),
                  
          slot_hashes: self.instruction.slot_hashes.expect("slot_hashes is not set"),
                  
          token_program: self.instruction.token_program.expect("token_program is not set"),
                  
          system_program: self.instruction.system_program.expect("system_program is not set"),
                  
          event_authority: self.instruction.event_authority.expect("event_authority is not set"),
                  
          program: self.instruction.program.expect("program is not set"),
                          __args: args,
            };
    instruction.invoke_signed_with_remaining_accounts(signers_seeds, &self.instruction.__remaining_accounts)
  }
}

#[derive(Clone, Debug)]
struct ExecutePublicAutomationCpiBuilderInstruction<'a, 'b> {
  __program: &'b solana_account_info::AccountInfo<'a>,
            authority: Option<&'b solana_account_info::AccountInfo<'a>>,
                satrush_config: Option<&'b solana_account_info::AccountInfo<'a>>,
                board: Option<&'b solana_account_info::AccountInfo<'a>>,
                round: Option<&'b solana_account_info::AccountInfo<'a>>,
                public_automation: Option<&'b solana_account_info::AccountInfo<'a>>,
                usd_mint: Option<&'b solana_account_info::AccountInfo<'a>>,
                automation_usd_ata: Option<&'b solana_account_info::AccountInfo<'a>>,
                board_usd_ata: Option<&'b solana_account_info::AccountInfo<'a>>,
                public_deployment: Option<&'b solana_account_info::AccountInfo<'a>>,
                miner: Option<&'b solana_account_info::AccountInfo<'a>>,
                slot_hashes: Option<&'b solana_account_info::AccountInfo<'a>>,
                token_program: Option<&'b solana_account_info::AccountInfo<'a>>,
                system_program: Option<&'b solana_account_info::AccountInfo<'a>>,
                event_authority: Option<&'b solana_account_info::AccountInfo<'a>>,
                program: Option<&'b solana_account_info::AccountInfo<'a>>,
                        selection_mask: Option<u32>,
        /// Additional instruction accounts `(AccountInfo, is_writable, is_signer)`.
  __remaining_accounts: Vec<(&'b solana_account_info::AccountInfo<'a>, bool, bool)>,
}

